"""Characterize native buffered base+shared penalty and threshold clipping."""
from pathlib import Path
import hashlib,json,re,subprocess,argparse
import numpy as np
R=Path(__file__).resolve().parents[1];B=R/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--channels',type=int,choices=[64,128],required=True);channels=ap.parse_args().channels;c=f'gf180_adaptation_sum{channels}_threshold_v1';d=B/'layout'/c;qp=d/'qualification.json';fp=d/'flat_cap_full_qualification.json';q=json.loads(qp.read_text());f=json.loads(fp.read_text());assert q['magic_drc_count']==q['gds_roundtrip_drc_count']==0 and q['lvs_unique'] and f['flat_lvs_unique'] and f['all_flat_extraction_node_ground_caps_verified'];src=d/(f['flat_subcircuit']+'_fullcap.spice');assert sha(src)==f['sha256'][src.relative_to(R).as_posix()];files={Path(__file__),qp,fp,src};text=src.read_text();ports=re.search(r'(?m)^\.subckt\s+'+f['flat_subcircuit']+r'\s+([^\n]+)',text.replace('\n+',' '))[1].split();assert ports==q['ports']
 load='gf180_mim_5x5_ports_routed';ld=B/'layout'/load;lq=ld/'qualification.json';ln=ld/(load+'.spice');files.update([lq,ln]);assert json.loads(lq.read_text())['lvs_unique'];models=B/'pdk/gf180_primitive_source/models/ngspice';files.update(models.rglob('*.spice'));pre='/workspace/'+models.relative_to(R).as_posix();stem=c+'_fullcap_native_add_clip_src'+sha(Path(__file__))[:12];rp=B/'results'/(stem+'.json');assert not rp.exists();dp=rp.with_suffix('.dat')
 lines=['Native shared adaptive threshold with buffered base and total penalty',f'.include {pre}/design.spice',f'.lib {pre}/sm141064.spice typical',f'.lib {pre}/sm141064.spice mimcap_typical',f'.lib {pre}/sm141064.spice res_typical','.param sw_stat_global=0 sw_stat_mismatch=0','.temp 27','.options method=gear reltol=1e-6 abstol=1e-16 vntol=1e-10 gmin=1e-18',text,ln.read_text(),'.global VSUBS','Vsub VSUBS 0 0','Vdd VDD 0 3.3','Vss VSS 0 0','Vcom VCOM 0 1.65','Vmin VMIN 0 1.55','Vmax VMAX 0 1.95',f'Ib BIAS 0 {3*(channels-1)+4}u','Vbase BASE_SOURCE 0 PWL(0 1.5 19u 1.5 20u 1.75 80u 1.75)','Rb BASE_SOURCE BASE 100','Xthreshold '+' '.join(ports)+' '+f['flat_subcircuit'],f'Xload EFFECTIVE_THRESHOLD VCOM VSS {load}','.control','set numdgt=15','set wr_singlescale','set wr_vecnames','tran .01u 80u 0 .1u','wrdata /workspace/'+dp.relative_to(R).as_posix()+' v(BASE) '+' '.join(f'v(PENALTY{i})' for i in range(channels))+' v(TOTAL) v(UNCLIPPED) v(EFFECTIVE_THRESHOLD) v(BIAS) i(Vdd)','quit','.endc','.end']
 extra=[]
 for j in range(channels):
  end=1.65+.32/channels
  points=f'0 1.65 19u 1.65 20u 1.7 39u 1.7 40u {end:.15g} 80u {end:.15g}' if j==0 else f'0 1.65 39u 1.65 40u {end:.15g} 80u {end:.15g}'
  extra.extend([f'Vpen{j} P_SOURCE{j} 0 PWL({points})',f'Rp{j} P_SOURCE{j} PENALTY{j} 100'])
 lines[lines.index('.control'):lines.index('.control')]=extra
 deck=B/'benches'/(stem+'.spice');deck.write_text('\n'.join(lines)+'\n');snap=B/'tools/source_snapshots'/(stem+'.py');snap.write_bytes(Path(__file__).read_bytes());files.update([deck,snap]);p=subprocess.run(['docker','run','--rm','--network','none','--memory','2g','--cpus','2','--volume',f'{R}:/workspace','--entrypoint','timeout','eventspikeseg:analog-ngspice47','120','ngspice','-b','/workspace/'+deck.relative_to(R).as_posix()],capture_output=True,text=True,timeout=135);log=p.stdout+p.stderr;lp=rp.with_suffix('.log');lp.write_text(log);files.add(lp)
 out=dict(module_simulation_completed=False,simulator_returncode=p.returncode,native_adaptation_sum_threshold_chain_observed=False,original_float_accuracy_accepted=False,full_5ms_population_service_accepted=False,full_chip_layout_complete=False,scope=f'Native full{channels}feature adaptation SUM tree with {24*channels+27}MOS,{4*channels}R,{12*channels}MIM and one final clipped-threshold operator. Sum-only8way internal stages; TOTAL=VCOM+sum all{channels}feature deviations at one pixel,not mean and not subset. Native physical grid,complete flat substrate/coupling C with per-node verification; source/GDS physical checks and flat exact primitive connectivity,realLEF. Separate native50fF output load.80us three sequential nominal fixtures:zero,onepositive channel,all channels summing0.32V. Reference master{3*(channels-1)+4}uA;1us analog source ramps and100ohm external source resistance. Center1.65,bounds1.55/1.95 illustrative,not trained voltage calibration. Actual model has adaptation widths64/128. Per-channel resident-product inputs externally held; producer connection,RMS,decision/subtractive-reset consumers,autonomous control,dense placement,model accuracy and full-population5ms service remain unfinished. Spaced characterization grid is not dense fullchip area. Local30mV bringup criterion only;typical27C/noise/mismatch off.')
 try:
  w=np.loadtxt(dp,skiprows=1);files.add(dp);ok=bool(p.returncode==0 and w.shape[1]==channels+7 and np.isfinite(w).all() and abs(w[-1,0]-80e-6)<1e-15 and 'aborted' not in log.lower());out['module_simulation_completed']=ok
  if ok:
   at=lambda j,u:float(np.interp(u*1e-6,w[:,0],w[:,j]));rows=[]
   for tag,u in [('zero_sum_lower_clip',18.),('one_active_channel',38.),('full_group_upper_clip',79.)]:
    base=at(1,u);terms=[at(j+2,u) for j in range(channels)];targettotal=1.65+sum(v-1.65 for v in terms);target=base+targettotal-1.65;bounded=max(1.55,min(target,1.95));rows.append(dict(case=tag,base_v=base,per_channel_penalties_v=terms,target_total_v=targettotal,total_v=at(channels+2,u),sum_error_v=at(channels+2,u)-targettotal,target_unclipped_v=target,unclipped_v=at(channels+3,u),addition_error_v=at(channels+3,u)-target,target_effective_v=bounded,effective_v=at(channels+4,u),effective_error_v=at(channels+4,u)-bounded))
   tail=w[:,0]>=40e-6;tt=w[tail,0];yy=w[tail,channels+2];outside=np.flatnonzero(abs(yy-yy[-1])>.001);out['all_input_ramp_to_sum_settle_1mV_of_recorded_final_us']=float((tt[outside[-1]+1] if len(outside) and outside[-1]+1<len(tt) else tt[0] if not len(outside) else tt[-1])*1e6-40);out['settling_scope']='Observed local sum settling to recorded final,not trained target or5ms population service; excludes producer read/write and scheduler overhead.'
   out['cases']=rows;out['max_sum_error_v']=max(abs(x['sum_error_v']) for x in rows);out['max_addition_error_v']=max(abs(x['addition_error_v']) for x in rows);out['max_clipped_threshold_error_v']=max(abs(x['effective_error_v']) for x in rows);out['native_adaptation_sum_threshold_chain_observed']=bool(out['max_clipped_threshold_error_v']<.03 and out['max_sum_error_v']<.03 and rows[0]['effective_v']<rows[1]['effective_v']<rows[2]['effective_v']);out['VDD_supply_energy_j_excludes_external_analog_sources']=float(np.trapezoid(-3.3*w[:,-1],w[:,0]))

 except Exception as e:out['postprocess_error']=str(e)
 out['sha256']={p.relative_to(R).as_posix():sha(p) for p in files};rp.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({k:v for k,v in out.items() if k!='sha256'},indent=2));assert out['module_simulation_completed']
if __name__=='__main__':main()
